import{_ as a,H as e,f as r,i as t}from"./chunks/framework.Cvt1eIE0.js";const d=JSON.parse('{"title":"第七章 百部族会議","description":"","frontmatter":{},"headers":[],"relativePath":"story/1-3.md","filePath":"story/1-3.md"}'),o={name:"story/1-3.md"};function h(s,p,i,n,K,l){return e(),r("div",null,[...p[0]||(p[0]=[t('<h1 id="第七章-百部族会議" tabindex="-1">第七章 百部族会議 <a class="header-anchor" href="#第七章-百部族会議" aria-label="Permalink to &quot;第七章 百部族会議&quot;">​</a></h1><p>黄金の冠を見つけてから、二年が経った。</p><p>三匹は旅を続けた。冠を持ったまま。しかし使わなかった。ただ、いつも荷物の一番奥に入れておいた。</p><p>時々、オーレックスは眠れない夜に冠を取り出した。溶岩の光の下で見ると、黄金は静かに光った。その光の中に、あの日聞いた声が戻ってくる気がした。</p><p>「希望そのものである。」</p><p>二年間、その言葉が消えなかった。</p><p>二十五歳になった、ある日。</p><p>三匹は焚き火を囲んでいた。</p><p>「もう、部族同士の争いを終わらせよう。」</p><p>オーレックスが言った。</p><p>静かな声だった。しかし、揺るぎなかった。</p><p>「みんなで一つの国を作るんだ。」</p><p>スターリンはすぐに立ち上がった。勢いよく立ち上がりすぎて、持っていたカップを倒した。</p><p>「待ってました！！」</p><p>ピックバーグは倒れたカップを静かに起こしながら頷いた。</p><p>「ついに、その時が来たんだね。」</p><p>「でも、どうやって？」</p><p>「話し合いだ。」</p><p>「百以上の部族が、話し合いなんかするか？」</p><p>「する場を作る。」</p><p>オーレックスは言った。「来なかった部族には、また声をかける。」</p><p>「拒否されたら？」</p><p>「また声をかける。」</p><p>「……諦めないんだな。」</p><p>「当然だ。」</p><p>こうして準備が始まった。各部族の長に書状を送った。断られた。また送った。無視された。また送った。</p><p>半年かけて、百を超える部族の長を集めることに成功した。</p><p>後に「百部族会議」と呼ばれる、ネザーの歴史を変える集会である。</p><hr><p>しかし会議は、始まった瞬間から大混乱だった。</p><p>広大な会議場に、百以上の部族長が集まった。しかし、そもそも同じ場所にいること自体が、彼らにとっては苦痛だった。</p><p>隣の族長を睨む者。</p><p>武器を置こうとしない者。</p><p>早々に席を立とうとする者。</p><p>「信用できるか！！こいつらが何をしたか知ってるか！！」</p><p>「先に攻めてきたのはお前たちだ！！」</p><p>「帰るぞ！！こんな場所にいられるか！！」</p><p>怒号が、石の天井に反響した。まるで全方向から攻撃されているようだった。</p><p>「駄目だ……。」</p><p>オーレックスは顔を伏せた。何百もの視線が自分に集まっていることを感じていた。しかし、言葉が出てこなかった。声を出しても、この怒号に飲まれる。</p><p>その時だった。</p><p>ドン！！</p><p>大地を揺るがすような音が響いた。全員が黙った。</p><p>スターリンが、巨大な斧の柄を床に叩きつけていた。両腕で振りかぶって、全力で。床に罅が入っていた。</p><p>「うるせえ！！」</p><p>スターリンの声は、怒号を上回った。</p><p>「少しはこいつの話を聞け！！」</p><p>全員の視線が、オーレックスへ向いた。</p><p>沈黙。</p><p>オーレックスはゆっくりと立ち上がった。膝が震えていた。見えないように、震えていた。</p><p>「僕は王になりたいわけじゃない。」</p><p>静かな声だった。しかし会議場に響いた。</p><p>「誰かを支配したいわけでもない。」</p><p>「ただ……」</p><p>「ただ、一つだけ聞かせてください。」</p><p>「争いで……何が残りましたか。」</p><p>誰も答えない。</p><p>「家族を失いましたか。」</p><p>誰かが俯く。</p><p>「仲間を失いましたか。」</p><p>また誰かが。</p><p>「村を失いましたか。」</p><p>「……。」</p><p>「僕は、両親を失いました。戦争で。」</p><p>「父は家族を守ろうとして。」</p><p>「母は他人を守ろうとして。」</p><p>「二人とも、帰ってこなかった。」</p><p>「それが、何十年も繰り返されてきた。」</p><p>「そんな時代を終わらせたい。」</p><p>声が震えた。しかし止まらなかった。</p><p>「一緒に生きよう。」</p><p>「一つの王国を作ろう。」</p><p>「争う力を、今度は守る力に変えよう。」</p><p>会議場が静まり返った。</p><p>長い沈黙。</p><p>誰も動かなかった。</p><p>やがて。</p><p>一人の族長が、武器をゆっくりと床に置いた。老いた族長だった。白髪で、顔に深い皴が刻まれていた。</p><p>「……もう疲れた。」</p><p>その声は、とても静かだった。しかし、全員に届いた。</p><p>また一人が武器を置く。「俺もだ。」</p><p>また一人。</p><p>また一人。</p><p>やがて、百以上の武器が床に並んだ。音が静かになっていくにつれて、広間の空気が、少しずつ変わっていった。</p><p>こうして。</p><p>百部族同盟が誕生した。</p><p>ネザーの歴史の中で、最も静かな瞬間に。</p><hr><h1 id="第八章-黒き牙" tabindex="-1">第八章 黒き牙 <a class="header-anchor" href="#第八章-黒き牙" aria-label="Permalink to &quot;第八章 黒き牙&quot;">​</a></h1><p>平和の夜明けは、まだ遠かった。</p><p>百部族同盟が誕生したその夜に、北の空が赤く染まった。しかしその赤は、溶岩の光ではなかった。</p><p>炎だった。</p><p>「北方の斥候から報告が来ました。」</p><p>使者が血相を変えて飛び込んできた。</p><p>「BLACK TUSK！北方の戦王が南へ進軍しています！！」</p><p>「軍勢は……？」</p><p>「数万。」</p><p>広間が凍りついた。</p><p>BLACK TUSK。</p><p>名前だけなら聞いたことがあった。北方を単独で制圧した戦士。黒い牙を持つ、最強の戦王。その言葉で語られる時、必ず「力こそ全て」という言葉が続いた。</p><p>「王国だと？笑わせるな。」</p><p>伝令が伝えた言葉は短かった。「弱者が集まったところで、力の前には無意味だ。蹴散らしてやろう。」</p><p>百部族同盟軍は動揺した。</p><p>「勝てない……！」</p><p>「数が違いすぎる！！まだ同盟ができたばかりで、連携も取れていない！！」</p><p>誰もが敗北を覚悟し始めた。</p><p>しかし。</p><p>オーレックスは逃げなかった。</p><p>逃げるという選択肢が、頭の中になかった。</p><p>「みんな。」</p><p>声を上げた。</p><p>「ここで逃げれば、また同じ悲劇が繰り返される。百部族が集まったことの意味が、消える。」</p><p>「戦おう。」</p><p>「力に力で挑むのか！？」</p><p>「いや。」</p><p>スターリンが前に出た。いつもの豪快な顔で。しかし目は笑っていない。</p><p>「知恵で戦う。」</p><p>ピックバーグが地図を広げた。</p><p>「勝機はある。地形を利用する。」</p><p>「具体的には――」</p><p>ピックバーグが作戦を語った。一時間後、全員が頷いた。</p><p>こうして。</p><p>黄金軍と北方軍の決戦が始まった。</p><hr><p>戦いは激しかった。</p><p>三日間、昼も夜もなく続いた。ネザーに昼夜はないのに、三日が経った。</p><p>スターリンは最前線にいた。常に最前線に。一歩も下がらず、大斧を振り続け、敵を押し返した。体中に傷を負いながら、それでも笑いながら戦い続けた。</p><p>「俺が止まったら後ろの奴らが死ぬ！！だから止まらねえ！！」</p><p>ピックバーグは後方から指揮を取った。地形を読み、罠を仕掛け、軍を動かした。一度も剣を抜かず、ただ作戦を立て続けた。</p><p>「戦うより守る方が、犠牲は少ない。すべての命を守りたい。」</p><p>そして四日目。</p><p>ついに、オーレックスとBLACK TUSKが対峙した。</p><p>両軍が、一瞬だけ動きを止めた。</p><p>一対一の対決。</p><p>「……貴様が王か。」</p><p>BLACK TUSKは巨大だった。三メートルはある体躯。黒い牙は、名前の通り。その目は冷たかった。しかし、その奥に何かが見えた気がした。</p><p>「そんなつもりはない。」</p><p>オーレックスは正面から答えた。</p><p>「だが。あなたの進軍を止めなければならない。だから戦う。」</p><p>「ほう。」</p><p>BLACK TUSKが斧を構えた。「死にたいか、小僧。」</p><p>斧が振り下ろされた。</p><p>ガァン！！</p><p>火花が散る。剣で受け止めた。腕が、痺れた。力が違う。圧倒的に。</p><p>しかしオーレックスは下がらなかった。押し返した。前に出た。</p><p>激しい戦いが続いた。互いの息が上がった。互いに傷を負った。</p><p>やがて。</p><p>オーレックスが一瞬の隙をついた。BLACK TUSKの体勢が崩れる。剣先が、喉元へ向く。</p><p>止まった。</p><p>「殺せ。」</p><p>BLACK TUSKが言った。目を開いたまま。負けを認めたように。しかし、誇りを失わない目で。</p><p>「……。」</p><p>オーレックスは剣を見た。剣先を。その先にある、巨大な戦王の喉を。</p><p>「……もう終わりにしよう。」</p><p>剣を下ろした。</p><p>「……？」</p><p>「憎しみは何も生まない。」</p><p>「お前も苦しんできたはずだ。」</p><p>BLACK TUSKは動かなかった。</p><p>「力しかなかった。力で支配してきた。他に方法を知らなかった。だからそれで生きてきた。」</p><p>「知っている。」</p><p>オーレックスは言った。「でも、他の方法がある。それを、一緒に見つけよう。」</p><p>BLACK TUSKは長い間、動かなかった。</p><p>風がない。音もない。</p><p>やがて。</p><p>巨大な体が、膝をついた。</p><p>「……お前こそ王だ。」</p><p>その声は静かだった。</p><p>戦場全体が、静まり返った。</p><p>「戦王が膝をついた……。」</p><p>「あのBLACK TUSKが……。」</p><p>「力に勝ったのか？」</p><p>「違う。」</p><p>誰かが言った。</p><p>「力を超えたんだ。」</p><p>こうして。</p><p>長き戦乱の時代は、幕を閉じた。</p><p>静かに。誰もが疲れた顔で、しかし目に光を取り戻しながら。</p><hr><h1 id="第九章-建国" tabindex="-1">第九章 建国 <a class="header-anchor" href="#第九章-建国" aria-label="Permalink to &quot;第九章 建国&quot;">​</a></h1><p>王国歴元年。</p><p>大陸の中央に、巨大都市が完成した。</p><p>GOLDEN BASTION。</p><p>黄金の要塞。</p><p>建設には三年かかった。三年間、百以上の部族が協力した。喧嘩もした。意見がぶつかることもあった。それでも止まらなかった。</p><p>「なんでそんなに熱心に作るんですか。」</p><p>ある日、若い職人にオーレックスが聞いた。</p><p>「先祖が作れなかったものだから。」</p><p>職人は答えた。</p><p>「争ってばかりで、何百年も作れなかった。だから今、作る。それだけです。」</p><p>その言葉を、オーレックスは忘れなかった。</p><hr><p>GOLDEN BASTIONには、様々なものが作られた。</p><p>巨大な王宮。</p><p>広大な市場。</p><p>王立図書館。</p><p>中央駅。</p><p>そして、各部族の紋章が彫られた石板が、城壁に並んで飾られた。どの部族も、省かれなかった。あの会議で最後まで抵抗した部族も、BLACK TUSKの部族も。全員の紋章が、並んでいた。</p><p>「全員の名前を残す。」</p><p>オーレックスが言い続けたことだった。「勝者も敗者もない。ここに集まった全員が、建国者だ。」</p><hr><p>王国歴元年の第一日目。</p><p>数十万の民が広場に集まった。</p><p>王立神殿の鐘が、巨大な音で鳴り響いた。その音はGOLDEN BASTION中に届いた。</p><p>スターリンは最前列にいた。腕を組んで。強がった顔で。しかし、目から水が流れていた。</p><p>「お前、泣いてるぞ。」</p><p>隣のピックバーグが言った。</p><p>「泣いてねえ！！目にゴミが入った！！」</p><p>「ゴミが両目に同時に入るのは確率的に稀だね。」</p><p>「うるせえ！！」</p><p>ピックバーグも笑っていた。珍しく、声を出して笑っていた。</p><p>祭壇の前。</p><p>オーレックスは立った。</p><p>あの日、古代の砦で見た冠が、今、目の前にある。</p><p>王立書記官が宣言した。</p><p>「ここに！」</p><p>「Aurex Goldtuskを！」</p><p>「PIGLIN KINGDOM初代国王！」</p><p>「KING PIGLIN Iとして即位せしめる！！」</p><p>鐘が鳴った。歓声が上がった。</p><p>「黄金王陛下万歳！！」</p><p>「KING PIGLIN I万歳！！」</p><p>「PIGLIN KINGDOM万歳！！！」</p><p>冠が、静かにオーレックスの頭上へ。</p><p>重かった。</p><p>あの日、砦で触れた時は軽かったのに。今は重かった。</p><p>しかし。</p><p>それは金の重さではなかった。</p><p>民の重さだった。</p><p>全員の希望の重さが、この冠にあった。だから重くて、だから下ろせない。</p><p>下ろさない。</p><p>初代国王となった彼は、民衆の前に立った。誰もが静かになるのを待って、それから言った。</p><p>「王国とは城壁ではない。」</p><p>「王国とは財宝ではない。」</p><p>「王国とは。」</p><p>「黄金の冠のもとに団結する民そのものである。」</p><p>歓声。</p><p>涙。</p><p>笑顔。</p><p>真紅の森で空を見上げていた少年は、今や、黄金の冠を戴く王となっていた。</p><p>二百年続く黄金王国。</p><p>PIGLIN KINGDOM。</p><p>その歴史は、この日、ここから始まった。</p><hr><h1 id="終章" tabindex="-1">終章 <a class="header-anchor" href="#終章" aria-label="Permalink to &quot;終章&quot;">​</a></h1><p>夜だった。</p><p>ネザーに夜はない。しかし、この日は夜だと思った。</p><p>王宮のバルコニーに一人立ち、オーレックスは空を見上げた。見慣れたネザーの天井が、今日は違って見えた。星がある気がした。</p><p>「本当に王様になっちゃったな。」</p><p>自分に言い聞かせるように、呟いた。</p><p>「お前が言うと笑えるな。」</p><p>後ろからスターリンが笑った。「最初からそうなる運命だったんだよ。」</p><p>いつの間にか、スターリンが隣に立っていた。相変わらず大きな体で、大斧を担いで。</p><p>「運命じゃない。」</p><p>反対側にピックバーグが立った。</p><p>「君が選び続けた結果だ。」</p><p>「助けることを選んだ。戦うことより守ることを選んだ。冠を置いて去ることもできたのに、王になることを選んだ。全部、君が選んだ。」</p><p>三人は並んで立った。</p><p>あの日、真紅の森の残骸の中で並んで旅を始めた三匹が、今、黄金王国の王宮のバルコニーに立っていた。</p><p>何かが変わった。</p><p>しかし、何も変わっていない。</p><p>「なあ。」</p><p>スターリンが言った。「これからどうすんだ？王様になって、戦争も終わって。やることあんのか？」</p><p>「ある。」</p><p>オーレックスは答えた。「山ほど。王国を作ることと、維持することは違う。これからが、本当の始まりだ。」</p><p>「……なんかそれ、旅に出る時にも似たようなこと言ってたな。」</p><p>「言ったかもしれない。」</p><p>「つまりまだ旅は終わってねえってことか。」</p><p>「そういうことかな。」</p><p>三人は笑った。</p><p>笑い声が、夜に消えた。</p><p>いや、夜ではない。しかし、笑い声は消えた。</p><p>消えた後も、温かさだけが残った。</p><p>三人は知らなかった。これから訪れる、新たな脅威を。黒曜石戦争の始まりを。失われた古代文明が目覚める予兆を。王国最大の危機が、すでに動き始めていることを。</p><p>しかし。</p><p>今この瞬間だけは、三人は笑っていた。</p><p>それで、十分だった。</p><hr><p>PIGLIN KING</p><p>第一巻 黄金王の誕生</p><p>完</p>',281)])])}const _=a(o,[["render",h]]);export{d as __pageData,_ as default};
